    const jobs: Array<{
      signal?: AbortSignal;
      finish: (pages: number) => void;
    }> = [];
    const t = await setup({
      compile: async (_source, options) =>
        new Promise((resolve) =>
          jobs.push({
            signal: options?.signal,
            finish: (count) =>
              resolve({
                pdf: new Blob([String(count)]),
                pages: [],
                pageCount: count,
              }),
          }),
        ),
    });
