import { afterAll, beforeEach, describe, expect, test } from "bun:test";
import { lockBrowserGlobalsForTestFile } from "./test-browser-globals-lock";

/**
 * The crash mirror is the one synchronous write left on the save path, and it
 * only runs when the tab is going away. It exists because an IndexedDB write
 * issued during `pagehide` is not guaranteed to commit.
 *
 * It replaced a global `twyne-document` key that was written on a timer while
 * the writer typed — blocking the main thread, and holding whichever folio
 * saved last regardless of which one the writer was in. These tests pin the
 * two properties that made that a bug: it is folio-scoped, and a mirror
 * belonging to another folio is never handed back.
 */

const originalWindow = globalThis.window;
const originalLocalStorage = globalThis.localStorage;
const releaseBrowserGlobalsLock = await lockBrowserGlobalsForTestFile();

const localStorageShim = (() => {
  const store: Record<string, string> = {};
  return {
    getItem: (k: string) => (k in store ? store[k] : null),
    setItem: (k: string, v: string) => {
      store[k] = v;
    },
    removeItem: (k: string) => {
      delete store[k];
    },
    clear: () => {
      for (const k of Object.keys(store)) delete store[k];
    },
  };
})();

Object.defineProperty(globalThis, "window", {
  configurable: true,
  value: { localStorage: localStorageShim },
});
Object.defineProperty(globalThis, "localStorage", {
  configurable: true,
  value: localStorageShim,
});

const { writeCrashMirror, readCrashMirror, clearCrashMirror } = await import(
  "./anti-tabula-rasa"
);

afterAll(() => {
  Object.defineProperty(globalThis, "window", {
    configurable: true,
    value: originalWindow,
  });
  Object.defineProperty(globalThis, "localStorage", {
    configurable: true,
    value: originalLocalStorage,
  });
  releaseBrowserGlobalsLock();
});

describe("crash mirror", () => {
  beforeEach(() => {
    localStorageShim.clear();
  });

  test("round-trips the manuscript for its own folio", () => {
    writeCrashMirror("f1", "<p>unsaved words</p>");
    expect(readCrashMirror("f1")).toBe("<p>unsaved words</p>");
  });

  test("is not returned for a different folio", () => {
    // The old global key would hand Folio II's body back to Folio I.
    writeCrashMirror("f1", "<p>folio one</p>");
    expect(readCrashMirror("f2")).toBeNull();
  });

  test("is empty when nothing was stashed", () => {
    expect(readCrashMirror("f1")).toBeNull();
  });

  test("clears", () => {
    writeCrashMirror("f1", "<p>body</p>");
    clearCrashMirror();
    expect(readCrashMirror("f1")).toBeNull();
  });

  test("the newest departure wins", () => {
    writeCrashMirror("f1", "<p>first</p>");
    writeCrashMirror("f1", "<p>second</p>");
    expect(readCrashMirror("f1")).toBe("<p>second</p>");
  });

  test("ignores a missing folio id rather than writing a global entry", () => {
    writeCrashMirror("", "<p>orphan</p>");
    expect(readCrashMirror("")).toBeNull();
    expect(readCrashMirror("f1")).toBeNull();
  });

  test("survives a corrupt entry without throwing", () => {
    localStorageShim.setItem("twyne:draft-crash-mirror", "{not json");
    expect(readCrashMirror("f1")).toBeNull();
  });
});
import type { Editor } from "@tiptap/core";
import type { ExportPayload } from "../exchange";
import { createRevisionSnapshot } from "../revision-history";
import {
  FOLIO_CONTENT_SAVED,
  loadFolioContentSnapshotFromIdb,
  saveFolioTypstToIdb,
  type FolioContentSavedDetail,
} from "../idb";
import { htmlToTypst, typstToHtml, reconcileTypstSource } from "./document";
import { compileTypstSource, type TypstCompilation } from "./client";
import {
  loadTypstSourceDraft,
  saveTypstSourceDraft,
  clearTypstSourceDraft,
} from "./source-drafts";

export interface TypstSessionState {
  source: string;
  dirty: boolean;
  conflict: boolean;
  status: string;
  error: string;
  pages: string[];
  pdfUrl: string;
  applying: boolean;
}
export interface TypstSession {
  changeSource(source: string): void;
  apply(): Promise<void>;
  discard(): Promise<void>;
  refreshProof(): void;
  destroy(): void;
}
export interface TypstSessionOptions {
  editor: Editor;
  folioId: string;
  readOnly: boolean;
  onState(state: TypstSessionState): void;
  getPayload(source: string): Promise<ExportPayload>;
  onPages(pageCount: number): void;
}

export interface TypstSessionDependencies {
  loadSnapshot: typeof loadFolioContentSnapshotFromIdb;
  saveSource: typeof saveFolioTypstToIdb;
  loadDraft: typeof loadTypstSourceDraft;
  saveDraft: typeof saveTypstSourceDraft;
  clearDraft: typeof clearTypstSourceDraft;
  compile: typeof compileTypstSource;
  saveRevision: typeof createRevisionSnapshot;
}

/** One folio owns its source draft, compiler cancellation and proof object URLs. */
export async function createTypstSession(
  options: TypstSessionOptions,
  overrides: Partial<TypstSessionDependencies> = {},
): Promise<TypstSession> {
  const { editor, folioId } = options;
  const deps: TypstSessionDependencies = {
    loadSnapshot: loadFolioContentSnapshotFromIdb,
    saveSource: saveFolioTypstToIdb,
    loadDraft: loadTypstSourceDraft,
    saveDraft: saveTypstSourceDraft,
    clearDraft: clearTypstSourceDraft,
    compile: compileTypstSource,
    saveRevision: createRevisionSnapshot,
    ...overrides,
  };
  let destroyed = false;
  let applying = false;
  let replacing = false;
  let revision = 0;
  let timer: ReturnType<typeof setTimeout> | undefined;
  let controller: AbortController | undefined;
  let baselineHtml = editor.getHTML();
  const visualHistory = new Set([baselineHtml]);
  const snapshot = await deps.loadSnapshot(folioId);
  let baseSource = snapshot?.typstSource;
  let committedHtml = snapshot?.html ?? baselineHtml;
  const recovered = await deps.loadDraft(folioId);
  baselineHtml = editor.getHTML();
  visualHistory.add(baselineHtml);
  let cleanSource =
    baseSource !== undefined
      ? reconcileTypstSource(baseSource, baselineHtml)
      : htmlToTypst(baselineHtml);
  const state: TypstSessionState = {
    source: recovered?.source ?? cleanSource,
    dirty: Boolean(recovered && recovered.source !== cleanSource),
    conflict: Boolean(
      recovered &&
        recovered.source !== cleanSource &&
        recovered.baseSource !== (baseSource ?? cleanSource),
    ),
    status: recovered ? "Recovered source draft" : "Preparing proof…",
    error: "",
    pages: [],
    pdfUrl: "",
    applying: false,
  };
  if (recovered && state.dirty) baseSource = recovered.baseSource;
  function emit() {
    if (destroyed) return;
    state.applying = applying;
    const editable = !options.readOnly && !state.dirty && !applying;
    if (editor.isEditable !== editable) editor.setEditable(editable, false);
    options.onState({ ...state, pages: [...state.pages] });
  }
  function sourceEvent() {
    window.dispatchEvent(
      new CustomEvent("twyne:typst-source-state", {
        detail: { folioId, source: state.source, pending: state.dirty },
      }),
    );
  }
  function draft() {
    if (destroyed || options.readOnly) return;
    void deps
      .saveDraft({
        folioId,
        source: state.source,
        baseSource: baseSource ?? cleanSource,
        updatedAt: Date.now(),
      })
      .catch((error) => {
        if (destroyed) return;
        state.error =
