  activeFolioId: null,
  folioKey: 0,
  rightPanelWidth: 340,
  newFolioFormOpen: false,
  confirmNukeOpen: false,
  // Default true to avoid a flash before the meta flag loads.
  signInToastDismissed: true,
  sharedLixId: null,
  sharedRole: null,
  joiningShared: false,
  joinError: null,
  workspaceError: null,
  activity: panelActivity(),
