/**
 * Assemble the full export payload for a folio.
 *
 * Both places a writer can export from — the File menu and the page-layout
 * tool — need the same set of parts: the manuscript, the brief, the
 * bibliography scoped to this folio, optionally the editors' marginalia, the
 * citation style, and the page setup. Gathering them in one place is what
 * stops the two paths from drifting into producing different documents from
 * the same folio.
 */

import type { ExportPayload } from "./exchange";
import type { LayoutSettings, ProjectBrief } from "../types";
import {
  loadFoliosFromIdb,
  loadFolioContentFromIdb,
  loadFolioContentSnapshotFromIdb,
  loadApparatusSettingsFromIdb,
} from "./idb";
import { reconcileTypstSource } from "./typst/document";
import { loadBibliographyForFolio } from "./bibliography";
import { loadPersonaNotesLocally } from "./convex-sync";

export interface FolioExportRequest {
  folioId: string | null | undefined;
  folioName: string;
  typstSource?: string;
  brief?: ProjectBrief | null;
  layout?: LayoutSettings;
  header?: string;
  footer?: string;
  /** Persona feedback is private working context unless the writer opts in. */
  includePersonaComments?: boolean;
}

export function shouldIncludePersonaComments(
  request: Pick<FolioExportRequest, "includePersonaComments">,
): boolean {
  return request.includePersonaComments === true;
}

/**
 * The freshest manuscript available.
 *
 * The open editor answers a synchronous event with its current HTML, which is
 * ahead of IndexedDB by however long the save debounce has left to run — so an
 * export never omits the last sentence the writer typed before reaching for
 * the menu. Falls back to the stored copy when no editor is mounted.
 */
export async function readActiveFolioHtml(
  activeFolioId: string | null | undefined,
): Promise<string> {
  if (typeof window !== "undefined") {
    let html = "";
    const receive = (e: Event) => {
      html = (e as CustomEvent).detail as string;
    };
    window.addEventListener("twyne:draft-html", receive);
    window.dispatchEvent(new CustomEvent("twyne:request-draft-html"));
    window.removeEventListener("twyne:draft-html", receive);
    if (html) return html;
  }
  if (activeFolioId) return await loadFolioContentFromIdb(activeFolioId);
  return "";
}

/** Read native source from the mounted editor before falling back to disk. */
export async function readActiveFolioTypstSource(
  folioId: string | null | undefined,
  html?: string,
): Promise<string | undefined> {
  const detail: {
    folioId: string | null | undefined;
    source?: string;
    pending?: boolean;
  } = { folioId };
  if (typeof window !== "undefined") {
    window.dispatchEvent(
      new CustomEvent("twyne:request-typst-source", { detail }),
    );
    if (detail.pending)
      throw new Error(
        "Apply or discard the pending Typst source changes before exporting or restoring a revision.",
      );
    if (detail.source !== undefined) return detail.source;
  }
  const snapshot = folioId
    ? await loadFolioContentSnapshotFromIdb(folioId)
    : null;
  return snapshot?.typstSource === undefined
    ? undefined
    : html !== undefined && html !== snapshot.html
      ? reconcileTypstSource(snapshot.typstSource, html)
      : snapshot.typstSource;
}

export async function buildFolioExportPayload(
  req: FolioExportRequest,
): Promise<ExportPayload> {
  const [html, folios, bibliography, apparatusSettings, marginalia] =
    await Promise.all([
      readActiveFolioHtml(req.folioId),
      loadFoliosFromIdb(),
      loadBibliographyForFolio(req.folioId),
      loadApparatusSettingsFromIdb(),
      shouldIncludePersonaComments(req)
        ? loadPersonaNotesLocally(req.folioId ?? undefined)
        : Promise.resolve([]),
    ]);

  const typstSource =
    req.typstSource ?? (await readActiveFolioTypstSource(req.folioId, html));
  return {
    typstSource,
    title: req.folioName || "Untitled",
    html,
    brief: req.brief ?? undefined,
    folios,
    bibliography,
    marginalia,
    citationStyle: apparatusSettings.defaultCitationStyle,
    layout: req.layout,
    header: req.header,
    footer: req.footer,
  };
}
export interface Persona {
  id: string;
  name: string;
  role: string;
  color: string;
  icon: string;
  description: string;
  focus: string;
  /**
   * Short fictional history used for role play and continuity. This is kept
   * separate from the writing instructions so an editor can have a life
   * without turning every response into exposition about that life.
   */
  backstory?: string;
  /**
   * The editor's critical doctrine: what they notice first, what they believe
   * good writing owes the reader, and how they decide what must change.
   */
  criticalMethod?: string;
  /**
   * Rich voice specification — diction, sentence rhythm, signature moves, and
   * what this editor never does. Injected into the system prompt so the five
   * personas read as genuinely different writers. Optional and backward
   * compatible: when absent, the generic shared wording is used.
   */
  voice?: string;
  /** Recurring rhetorical habits that make this editor recognizable. */
  signatureMoves?: string[];
  /** Words, tones, structures, and other-persona behaviors this editor avoids. */
  avoidances?: string[];
  /** One or two few-shot lines written in this persona's voice. */
  sampleLines?: string[];
  /**
   * Provider voice used when this editor is read aloud (e.g. "onyx").
   * The `voice` lore above doubles as the TTS voice direction, so the two
   * together are what make five editors sound like five people.
   */
  speechVoice?: string;
  /**
   * Per-provider voice overrides, keyed by {@link AiProviderType}. Providers
   * name voices in incompatible ways — OpenAI uses names like "onyx", Fish
   * Audio uses a 32-character voice-model id — so a single field cannot serve
   * both. {@link Persona.speechVoice} is the fallback when a provider has no
   * entry here.
   */
  speechVoices?: Partial<Record<AiProviderType, string>>;
  /** Optional per-persona generation prefs (honored on the BYOK client path). */
  providerId?: string;
  model?: string;
  temperature?: number;
}

export interface PersonaFeedback {
  /** Folio whose manuscript this note belongs to. */
  folioId?: string;
  personaId: string;
  personaName: string;
  personaColor: string;
  feedback: string;
  /** PostHog AI generation handle used to attach contextual feedback. */
  traceId?: string;
  paragraphIndex?: number;
  timestamp: number;
  type: "encouragement" | "suggestion" | "critique" | "perspective";
  /** Exact sentence from the draft this note is pinned to, when one was found. */
  anchor?: string;
  /** Stable id shared between the feed card and the inline mark in the manuscript. */
  noteId?: string;
  /** Title of the brief the note was filed against, for the timeline. */
  briefTitle?: string;
  /**
   * How this note came to exist. `"convened"` (the default when absent) means
   * the writer asked; `"background"` means the room read new material on its
   * own while the writer was working, and the note should be presented more
   * quietly.
   */
  origin?: "convened" | "background";
}

/** Payload of the `twyne:persona-notes` window event: notes to pin inline. */
export interface PersonaNotePayload {
  id: string;
  author: string;
  color: string;
  label: string;
  note: string;
  quote: string;
  briefTitle?: string;
}

export interface RubricCriterion {
  id: string;
  label: string;
  description: string;
  score: number;
  maxScore: number;
  feedback: string;
}

/**
 * One line of the writer's rubric configuration.
 *
 * The spine — the criteria Twyne ships — stays fixed so a score means the same
 * thing from one pass to the next, and so the trend line is honest. What the
 * writer controls is the weighting, whether a spine criterion is shown at all,
 * and any number of criteria of their own that the room will judge alongside
 * them. Spine entries can be disabled and reweighted but never deleted; that
 * is what keeps two runs comparable.
 */
export interface RubricCriterionSpec {
  id: string;
  label: string;
  description: string;
  source: "spine" | "custom";
  enabled: boolean;
  /** Relative weight within the criteria list. 1 is the default. */
  weight: number;
}

/** The criteria Twyne ships. Order is the order they render in. */
export const SPINE_CRITERIA: ReadonlyArray<
  Pick<RubricCriterionSpec, "id" | "label" | "description">
> = [
  {
    id: "targetFit",
    label: "On brief",
    description:
      "Is the draft about what the brief asks, for the reader it names? Judged apart from how well it's written.",
  },
  {
    id: "thesis",
    label: "Argument",
    description:
      "Is the main point clear, and does the draft make the case for it?",
  },
  {
    id: "evidence",
    label: "Evidence",
    description:
      "Are the claims backed by sources, examples or figures that actually fit them?",
  },
  {
    id: "sufficiency",
    label: "Development",
    description: "Is there enough on-topic material to earn the main point?",
  },
  {
    id: "integrity",
    label: "Straight talk",
    description:
      "Free of padding, vague words, repetition and claims stated more strongly…335 tokens truncated… avoid. */
  feedbackNotes: string;
  /** Primary literary genre or form the writer produces. */
  primaryGenre?: string;
  /** The writer's background or experience level. */
  experienceLevel?: WriterExperienceLevel;
  /** Priority feedback dimensions the writer cares most about. */
  feedbackFocus?: string[];
  /** How much praise/encouragement the writer wants alongside critique. */
  praisePreference?: PraisePreference;
  /** Preferred critique framing (direct prescriptions, Socratic questions, or analytical diagnosis). */
  critiqueTone?: CritiqueTone;
  /** How strictly the room must respect the writer's established facts and domain truths. */
  factChecking?: FactAdherenceMode;
  /** Things the writer specifically dislikes or wants the room to avoid in feedback. */
  feedbackAvoid?: string;
}

export const DEFAULT_WRITER_PROFILE: WriterProfile = {
  displayName: "",
  personalFacts: "",
  feedbackStyle: "balanced",
  feedbackNotes: "",
};

/** Writer-level preferences (identity, feedback, and onboarding). */
export interface WriterSettings {
  /** Form-based AntiTabulaRasa vs the conversational interview. */
  interviewStyle: "form" | "conversational";
  /** Private, account-local context included in editorial-room prompts. */
  profile: WriterProfile;
}

export const DEFAULT_WRITER_SETTINGS: WriterSettings = {
  interviewStyle: "form",
  profile: { ...DEFAULT_WRITER_PROFILE },
};

export type ApparatusCitationStyle = "mla" | "apa" | "chicago";

/**
 * Where claim-checking searches go.
 *
 *  - hosted:           Twyne's own service, using the server's provider key.
 *  - search-api:       a search API called straight from this browser (BYOK),
 *                      configured by `searchBackend`.
 *  - model-web-search: the writer's own model provider, with web search on.
 *  - web-mcp:          tools discovered from the writer's MCP servers.
 */
export type ApparatusResearchProvider =
  | "hosted"
  | "search-api"
  | "model-web-search"
  | "web-mcp";

/**
 * Search APIs Twyne knows how to speak without configuration. "custom" covers
 * anything else that returns JSON: give it a URL and where the results live.
 */
export type SearchBackendId =
  | "tinyfish"
  | "exa"
  | "tavily"
  | "brave"
  | "serper"
  | "custom";

export interface SearchBackendConfig {
  id: SearchBackendId;
  apiKey: string;
  /** Overrides the adapter's built-in endpoint. Required for "custom". */
  baseUrl: string;
  /**
   * "custom" only: dotted path to the results array in the response
   * (e.g. "data.results"). Empty means search the response for the first
   * array of objects that carry a url.
   */
  resultsPath: string;
}

export const DEFAULT_SEARCH_BACKEND: SearchBackendConfig = {
  id: "tinyfish",
  apiKey: "",
  baseUrl: "",
  resultsPath: "",
};

/** Streamable HTTP is the current spec transport; SSE is the deprecated one. */
export type McpTransportKind = "http" | "sse";

/**
 * How to reach the server. Most hosted MCP servers send no CORS headers, so
 * "auto" tries the browser first (token stays on the device) and relays through
 * Convex only once a direct attempt has failed.
 */
export type McpConnectionMode = "auto" | "direct" | "proxy";

export interface McpServerConfig {
  id: string;
  label: string;
  url: string;
  transport: McpTransportKind;
  bearerToken: string;
  enabled: boolean;
  connection: McpConnectionMode;
  /** Tool that answers apparatus claim searches. Empty means auto-detect. */
  searchToolName: string;
  /** Offer this server's tools to the model while drafting. */
  exposeToModel: boolean;
  /** Treat this server's resources as citable knowledge-base material. */
  useResources: boolean;
}

export const DEFAULT_MCP_SERVER: Omit<McpServerConfig, "id"> = {
  label: "",
  url: "",
  transport: "http",
  bearerToken: "",
  enabled: true,
  connection: "auto",
  searchToolName: "",
  exposeToModel: false,
  useResources: true,
};

export interface ApparatusSettings {
  defaultCitationStyle: ApparatusCitationStyle;
  aiEnhanceCitations: boolean;
  flagMissingSources: boolean;
  /** Insert newly researched sources as footnotes at their draft anchors. */
  autoInsertFootnotes: boolean;
  researchProvider: ApparatusResearchProvider;
  searchBackend: SearchBackendConfig;
  /** Sources requested per claim, whichever provider answers. */
  maxResults: number;
  mcpServers: McpServerConfig[];
}

export const DEFAULT_APPARATUS_SETTINGS: ApparatusSettings = {
  defaultCitationStyle: "mla",
  aiEnhanceCitations: true,
  flagMissingSources: false,
  autoInsertFootnotes: false,
  researchProvider: "hosted",
  searchBackend: { ...DEFAULT_SEARCH_BACKEND },
  maxResults: 8,
  mcpServers: [],
};

export interface AiFeatureOverride {
  providerId?: string;
  model?: string;
  temperature?: number;
  maxTokens?: number;
  voice?: string;
  speed?: number;
  responseFormat?: "mp3" | "opus" | "aac" | "flac" | "wav" | "pcm";
  instructions?: string;
}

export interface AiSettings {
  advancedMode: boolean;
  providers: AiProviderConfig[];
  defaultProviderId: string | null;
  perFeature: Partial<Record<AiFeature, AiFeatureOverride>>;
  showProviderTags: boolean;
  /** Which model answers Twyne's typed judgements. Absent = Twyne's hosted Jev. */
  judgement?: JudgementSettings;
}

/**
 * The judgement model — the one that answers typed questions (yes/no, pick
 * one, rate) for the rubric, quick review, margin tools and passage triage.
 * It never writes prose; it returns calibrated probabilities.
 *
 *   twyne     Jev through Twyne's account (the default)
 *   typesafe  Jev on the writer's own TypeSafe key, relayed by Twyne's server
 *             because TypeSafe's API does not accept browser requests
 *   endpoint  any server speaking the same `/v1/systemone` API — Kev on this
 *             computer, on Modal or RunPod — called straight from the browser
 */
export interface JudgementSettings {
  source: "twyne" | "typesafe" | "endpoint";
  typesafeKey?: string;
  /** Defaults to `jev-latest`. */
  typesafeModel?: string;
  /** Base URL without the path, e.g. `http://127.0.0.1:8009`. */
  endpointUrl?: string;
  endpointKey?: string;
  /** Defaults to `kev-latest`. */
  endpointModel?: string;
}

export const DEFAULT_AI_SETTINGS: AiSettings = {
  advancedMode: false,
  providers: [],
  defaultProviderId: null,
  perFeature: {},
  showProviderTags: false,
};

/* ── Provider metadata (labels, defaults) ───────────────────────── */

export interface ProviderMeta {
  type: AiProviderType;
  label: string;
  defaultModels: string[];
  needsBaseUrl: boolean;
  defaultBaseUrl?: string;
  apiKeyOptional?: boolean;
  defaultApiKey?: string;
  /**
   * Speaks and listens but cannot think. A voice-only provider is never
   * offered to the persona, rubric or interview features, and — crucially —
   * having one configured does not make {@link hasConfiguredAiProvider} true,
   * because those features would then take the BYOK path and find no model.
   */
  voiceOnly?: boolean;
}

/** Provider types that do speech but not language. */
export const VOICE_ONLY_PROVIDER_TYPES: ReadonlyArray<AiProviderType> = [
  "fishaudio",
  "supertonic",
];

export const PROVIDER_METAS: ProviderMeta[] = [
  {
    type: "openai",
