    ],
    needsBaseUrl: false,
  },
  {
    type: "openai-compatible",
    label: "OpenAI-compatible",
    defaultModels: [],
    needsBaseUrl: true,
  },
  {
    type: "deepseek",
    label: "DeepSeek",
    defaultModels: [],
    needsBaseUrl: true,
    defaultBaseUrl: "https://api.deepseek.com",
  },
  {
    type: "openrouter",
    label: "OpenRouter",
    defaultModels: [],
    needsBaseUrl: true,
    defaultBaseUrl: "https://openrouter.ai/api/v1",
  },
  {
    type: "ollama",
    label: "Ollama",
    defaultModels: [],
    needsBaseUrl: true,
    defaultBaseUrl: "http://127.0.0.1:11434/v1",
    apiKeyOptional: true,
    defaultApiKey: "ollama",
  },
  {
